const analyticsTopUsers = `-- name: AnalyticsTopUsers :many
SELECT t.user_id, u.username, COALESCE(p.name, '')::text AS plan_name, t.bytes
FROM (SELECT h.user_id, SUM(h.up + h.down)::bigint AS bytes
      FROM user_traffic_hourly h
      WHERE h.hour >= $1
      GROUP BY h.user_id
      HAVING SUM(h.up + h.down) > 0
      ORDER BY 2 DESC, h.user_id
      LIMIT $2) t
JOIN end_user u ON u.id = t.user_id AND u.deleted_at IS NULL
LEFT JOIN plan p ON p.id = u.plan_id
ORDER BY t.bytes DESC, t.user_id
`

type AnalyticsTopUsersParams struct {
	Since    pgtype.Timestamptz
	RowLimit int32
}

type AnalyticsTopUsersRow struct {
	UserID   int64
	Username string
	PlanName string
	Bytes    int64
}

func (q *Queries) AnalyticsTopUsers(ctx context.Context, arg AnalyticsTopUsersParams) ([]AnalyticsTopUsersRow, error) {
	rows, err := q.db.Query(ctx, analyticsTopUsers, arg.Since, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AnalyticsTopUsersRow{}
	for rows.Next() {
		var i AnalyticsTopUsersRow
		if err := rows.Scan(
			&i.UserID,
			&i.Username,
			&i.PlanName,
			&i.Bytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

