const analyticsUserBreakdown = `-- name: AnalyticsUserBreakdown :one
SELECT COUNT(*) FILTER (WHERE status = 'active')::int AS active,
       COUNT(*) FILTER (WHERE status = 'limited')::int AS limited,
       COUNT(*) FILTER (WHERE status = 'expired')::int AS expired,
       COUNT(*) FILTER (WHERE status = 'disabled')::int AS disabled,
       COUNT(*) FILTER (WHERE expires_at < $1::timestamptz)::int AS expiry_expired,
       COUNT(*) FILTER (WHERE expires_at >= $1::timestamptz AND expires_at < $2::timestamptz)::int AS expiry_week,
       COUNT(*) FILTER (WHERE expires_at >= $2::timestamptz AND expires_at < $3::timestamptz)::int AS expiry_month,
       COUNT(*) FILTER (WHERE expires_at >= $3::timestamptz)::int AS expiry_later,
       COUNT(*) FILTER (WHERE expires_at IS NULL)::int AS expiry_never,
       COUNT(*) FILTER (WHERE expires_at >= $1::timestamptz AND expires_at < $2::timestamptz
                              AND NOT auto_renew)::int AS expiry_week_manual,
       COUNT(*) FILTER (WHERE status = 'active'
                              AND (last_used_at IS NULL OR last_used_at < $4::timestamptz))::int AS silent
FROM end_user
WHERE deleted_at IS NULL
`

type AnalyticsUserBreakdownParams struct {
	NowAt        pgtype.Timestamptz
	WeekEnd      pgtype.Timestamptz
	MonthEnd     pgtype.Timestamptz
	SilentBefore pgtype.Timestamptz
}

type AnalyticsUserBreakdownRow struct {
	Active           int32
	Limited          int32
	Expired          int32
	Disabled         int32
	ExpiryExpired    int32
	ExpiryWeek       int32
	ExpiryMonth      int32
	ExpiryLater      int32
	ExpiryNever      int32
	ExpiryWeekManual int32
	Silent           int32
}

// 状态分布、到期分布与沉默用户，一次扫描
func (q *Queries) AnalyticsUserBreakdown(ctx context.Context, arg AnalyticsUserBreakdownParams) (AnalyticsUserBreakdownRow, error) {
	row := q.db.QueryRow(ctx, analyticsUserBreakdown,
		arg.NowAt,
		arg.WeekEnd,
		arg.MonthEnd,
		arg.SilentBefore,
	)
	var i AnalyticsUserBreakdownRow
	err := row.Scan(
		&i.Active,
		&i.Limited,
		&i.Expired,
		&i.Disabled,
		&i.ExpiryExpired,
		&i.ExpiryWeek,
		&i.ExpiryMonth,
		&i.ExpiryLater,
		&i.ExpiryNever,
		&i.ExpiryWeekManual,
		&i.Silent,
	)
	return i, err
}

